+                    System.arraycopy(bytes, bytes.length - tmp.length, tmp, 0, tmp.length);
+                    return tmp;
+                } else if (qLength > bytes.length) {
+                    byte[] tmp = new byte[qLength];
+                    System.arraycopy(bytes, 0, tmp, tmp.length - bytes.length, bytes.length);
